type PerfSample = {
  release: string;
  route: string;
  entryType: string;
  startTime: number;
  duration: number;
  interaction?: string;
};

function observePerformance(type: string) {
  if (!PerformanceObserver.supportedEntryTypes.includes(type)) return;

  const observer = new PerformanceObserver((list, _observer, options) => {
    for (const entry of list.getEntries()) {
      if (!shouldSampleSession()) continue;
      enqueueTelemetry({
        release: APP_VERSION,
        route: sanitizeRoute(location.pathname),
        entryType: entry.entryType,
        startTime: entry.startTime,
        duration: entry.duration,
        interaction: currentInteractionName(),
      } satisfies PerfSample);
    }

    if (options?.droppedEntriesCount) {
      incrementMetric('performance_entries_dropped', options.droppedEntriesCount);
    }
  });

  observer.observe({ type, buffered: true });
}

observePerformance('longtask');
observePerformance('event');
observePerformance('long-animation-frame');

