type Delta = { sequence: number; entityId: string; value: number };
type Snapshot = { cursor: number; entities: Map<string, number> };

class BoundedCoalescingQueue {
  private latestByEntity = new Map<string, Delta>();
  constructor(private readonly maxEntities: number) {}

  push(delta: Delta) {
    if (this.latestByEntity.has(delta.entityId)) {
      this.latestByEntity.set(delta.entityId, delta);
      return { accepted: true, coalesced: true };
    }
    if (this.latestByEntity.size >= this.maxEntities) {
      return { accepted: false, reason: 'capacity' as const };
    }
    this.latestByEntity.set(delta.entityId, delta);
    return { accepted: true, coalesced: false };
  }

  drain(): Delta[] {
    const batch = [...this.latestByEntity.values()];
    this.latestByEntity.clear();
    return batch.sort((a, b) => a.sequence - b.sequence);
  }
}

let expectedSequence = initialSnapshot.cursor + 1;
const queue = new BoundedCoalescingQueue(10_000);

function onDelta(delta: Delta) {
  if (delta.sequence < expectedSequence) return; // duplicate/replay
  if (delta.sequence > expectedSequence) {
    requestReplayOrSnapshot(expectedSequence, delta.sequence);
    return;
  }
  expectedSequence += 1;
  const result = queue.push(delta);
  if (!result.accepted) enterReducedSubscriptionMode();
}

setInterval(() => {
  const batch = queue.drain();
  if (batch.length) aggregationWorker.postMessage({ type: 'APPLY', batch, viewVersion });
}, 100);

type CrossTabMessage = {
  protocol: 1;
  id: string;
  source: string;
  type: 'SESSION_INVALIDATED' | 'DRAFT_UPDATED' | 'LEADER_HEARTBEAT';
  revision: number;
  payload?: { draftId?: string; leaseUntil?: number };
};

const tabId = crypto.randomUUID();
const seen = new Set<string>();
const channel = new BroadcastChannel('app-coordination-v1');

function publish(message: Omit<CrossTabMessage, 'protocol' | 'id' | 'source'>) {
  channel.postMessage({ protocol: 1, id: crypto.randomUUID(), source: tabId, ...message } satisfies CrossTabMessage);
}

channel.addEventListener('message', async (event: MessageEvent<CrossTabMessage>) => {
  const message = event.data;
  if (message.protocol !== 1 || message.source === tabId || seen.has(message.id)) return;
  seen.add(message.id);

  if (message.type === 'SESSION_INVALIDATED') {
    authStore.clearLocalSession();
    await authStore.revalidateWithServer();
  }

  if (message.type === 'DRAFT_UPDATED' && message.payload?.draftId) {
    await drafts.reconcile(message.payload.draftId, message.revision);
  }
  // Không phát lại message nhận được.
});

export async function logoutEverywhere() {
  await fetch('/api/session', { method: 'DELETE', credentials: 'same-origin' });
  authStore.clearLocalSession();
  publish({ type: 'SESSION_INVALIDATED', revision: Date.now() });
}

