type VendorPolicy = {
  id: string;
  ownerTeam: string;
  purpose: 'essential' | 'functional' | 'analytics' | 'marketing';
  consentCategory?: 'analytics' | 'ads';
  allowedRoutes: RegExp[];
  src: string;
  integrity?: string;
  maxLoadMs: number;
  killSwitchKey: string;
};

function appendGovernedScript(policy: VendorPolicy): Promise<void> {
  return new Promise((resolve, reject) => {
    const script = document.createElement('script');
    let settled = false;

    const finish = (result: 'load' | 'error' | 'timeout') => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      script.onload = null;
      script.onerror = null;

      if (result === 'load') resolve();
      else {
        script.remove();
        reject(new Error(`Vendor ${policy.id}: ${result}`));
      }
    };

    const timer = window.setTimeout(() => finish('timeout'), policy.maxLoadMs);
    script.async = true;
    script.src = policy.src;
    script.nonce = getCspNonce();
    script.crossOrigin = 'anonymous';
    if (policy.integrity) script.integrity = policy.integrity;
    script.onload = () => finish('load');
    script.onerror = () => finish('error');
    document.head.append(script);
  });
}

export async function loadVendor(policy: VendorPolicy): Promise<void> {
  if (!policy.allowedRoutes.some((route) => route.test(location.pathname))) return;
  if (remoteConfig.isDisabled(policy.killSwitchKey)) return;
  if (policy.consentCategory && !consent.has(policy.consentCategory)) return;

  const startedAt = performance.now();
  try {
    await appendGovernedScript(policy);
    recordVendorMetric(policy.id, 'loaded', performance.now() - startedAt);
  } catch (error) {
    // remove() không thể hoàn tác code đã execute; kill switch phải chặn trước load.
    recordVendorFailure(policy.id, error);
    renderVendorFallback(policy.id);
  }
}

